using System.Linq;
using UnityEngine;
namespace BWVR {
public sealed partial class VillageResources {
 public CarryItem DeliveryItem{get;private set;}public bool DeliveryClaimed{get;private set;}ToolTechnologyState boundTools;CreatureHybrid deliveryGod;GameObject deliveryAxe,deliveryHoe;bool restoreDelivery;float deliverySearch,destinationUntil,deliveryGrace;Vector3 destinationPerson,cachedDestination;bool destinationFound;int deliveryApproach;
 public ToolDeliveryState Delivery=>Season.Tools.delivery;
 public float DeliveryWood=>Delivery?.Active==true?2:0;public float DeliveryResin=>Delivery?.Active==true?ToolTechnologyState.ResinCost(Delivery.tool):0;
 public VillagerSocial DeliveryPerson=>Delivery?.Active==true?Gatherers[Delivery.recipient].GetComponent<VillagerSocial>():null;
 public bool ToolDeliveryWaiting(int actor)=>Delivery?.Active==true&&Delivery.recipient==actor;
 public bool DeliveryFeasible=>Delivery?.Active==true&&!Season.paused&&!DeliveryClaimed&&DeliveryItem!=null&&!DeliveryItem.held&&DeliveryPerson!=null&&!DeliveryPerson.GetComponent<CarryItem>().held&&DeliveryPerson.Memory.injury<.7f&&!DeliveryPerson.RecentFright&&!Season.Tools.learners[Delivery.recipient].Owns(Delivery.tool)&&State.wood>=2&&State.resin>=ToolTechnologyState.ResinCost(Delivery.tool)&&TryToolDestination(out _);
 public bool CanOfferDelivery=>DeliveryFeasible&&DeliveryItem.GetComponent<CreatureAffordance>().Available&&deliveryGod.CanSeeCue(DeliveryItem.GetComponent<HybridTarget>(),false,true);
 public bool TryToolDestination(out Vector3 at){at=default;var person=DeliveryPerson;if(person==null||deliveryGod==null)return false;if(Season.Hybrid.time<destinationUntil&&(person.transform.position-destinationPerson).sqrMagnitude<Navigation.Scale*Navigation.Scale*4){at=cachedDestination;return destinationFound;}destinationUntil=Season.Hybrid.time+.5f;if(destinationFound&&(person.transform.position-destinationPerson).sqrMagnitude<Navigation.Scale*Navigation.Scale*4&&Vector3.Distance(cachedDestination,person.transform.position)<=Navigation.Scale*10&&deliveryGod.GetComponent<IslandNavigator>().BodyClear(cachedDestination,cachedDestination)&&deliveryGod.CanReach(cachedDestination)){at=cachedDestination;return true;}destinationPerson=person.transform.position;destinationFound=false;var side=deliveryGod.transform.position-person.transform.position;side.y=0;if(side.sqrMagnitude<1e-10f)side=Vector3.back;side.Normalize();for(int i=0;i<8;i++){var wanted=person.transform.position+Quaternion.Euler(0,(i+deliveryApproach)*45,0)*side*Navigation.Scale*6;if(!Navigation.Sample(wanted,Navigation.creature,4,out var foot))continue;foot=Navigation.ProjectFoot(foot,Navigation.creature);float gap=Vector3.Distance(foot,person.transform.position)/Navigation.Scale;if(gap>10||gap<Navigation.creature.radius+Navigation.villager.radius+.75f||!deliveryGod.GetComponent<IslandNavigator>().BodyClear(foot,foot)||!deliveryGod.CanReach(foot))continue;at=cachedDestination=foot;destinationFound=true;return true;}return false;}
 void BindToolDelivery(){
  if(deliveryGod==null)deliveryGod=Navigation.GetComponentInChildren<CreatureHybrid>();if(DeliveryClaimed)deliveryGod.Interrupt("Tool delivery state changed");DeliveryClaimed=false;destinationUntil=0;deliveryApproach=0;boundTools=Season.Tools;restoreDelivery=Delivery?.Active==true;deliveryGrace=restoreDelivery?Season.Hybrid.time+12:0;deliverySearch=0;
  if(DeliveryItem==null){var root=new GameObject("Workshop tool — bring to its waiting villager");root.transform.SetParent(transform,false);root.transform.position=StoreApproach;DeliveryItem=root.AddComponent<CarryItem>();DeliveryItem.kind=Offering.Toy;root.AddComponent<SourcedPickup>().modelPath="SettlementProps/tool-axe-upgraded";var box=root.AddComponent<BoxCollider>();box.center=Vector3.up*Navigation.Scale*2.5f;box.size=new Vector3(3,5,3)*Navigation.Scale;root.AddComponent<ToolDelivery>().world=this;var a=root.AddComponent<CreatureAffordance>();a.kind=CreatureAffordance.Kind.Turn;deliveryGod.RegisterObject(a,"workshop-tool-delivery");deliveryAxe=Prop("tool-axe-upgraded","Workshop axe",root.transform.position,5,root.transform);deliveryHoe=Prop("tool-hoe-upgraded","Workshop hoe",root.transform.position,5,root.transform);root.AddComponent<SpatialTarget>().invoke=()=>deliveryGod.Guide(GuidanceIntent.Help,root.GetComponent<HybridTarget>());}
  DeliveryItem.held=false;DeliveryItem.GetComponent<Collider>().enabled=true;DeliveryView();
 }
 void DeliveryView(){if(DeliveryItem==null)return;bool active=Delivery?.Active==true;bool visible=active||DeliveryItem.held;DeliveryItem.gameObject.SetActive(visible);deliveryAxe.SetActive(visible&&Delivery?.tool==VillageTool.BoundAxe);deliveryHoe.SetActive(visible&&Delivery?.tool==VillageTool.CultivatingHoe);DeliveryPose(deliveryAxe.transform);DeliveryPose(deliveryHoe.transform);if(Delivery!=null)DeliveryItem.GetComponent<SourcedPickup>().modelPath="SettlementProps/"+(Delivery.tool==VillageTool.BoundAxe?"tool-axe-upgraded":"tool-hoe-upgraded");}
 void DeliveryPose(Transform art){art.localRotation=DeliveryItem.held?Quaternion.Euler(0,0,-90):Quaternion.identity;art.localPosition=DeliveryItem.held?Vector3.left*Navigation.Scale*2.5f:Vector3.zero;}
 void AdvanceToolDelivery(float dt){
  if(boundTools!=Season.Tools)BindToolDelivery();if(Navigation.TreeNavigationPending)return;
  if(restoreDelivery){restoreDelivery=false;if(!Navigation.Sample(Navigation.ToWorld(Delivery.grounded),Navigation.creature,4,out var at))at=StoreApproach;DeliveryItem.transform.position=DeliveryItem.home=Navigation.ProjectFoot(at,Navigation.creature);}
  if(Delivery?.Active==true){var d=Delivery;if(d.playerArrivalPending){d.playerArrivalPending=false;ConfirmToolDelivery(ToolDeliverySource.Player);}if(d.Active&&(Season.Tools.learners[d.recipient].Owns(d.tool)||State.wood<2||State.resin<ToolTechnologyState.ResinCost(d.tool)||Season.Hybrid.time>=d.expiresAt||!DeliveryClaimed&&!DeliveryItem.held&&Season.Hybrid.time>=Mathf.Max(d.openedAt+12,deliveryGrace))){d.status=Season.Hybrid.time>=d.expiresAt||Season.Hybrid.time>=Mathf.Max(d.openedAt+12,deliveryGrace)?ToolDeliveryStatus.Expired:ToolDeliveryStatus.Unavailable;d.playerArrivalPending=false;if(DeliveryClaimed)deliveryGod.Interrupt("Tool delivery no longer available");}CaptureToolDelivery();DeliveryView();return;}
  DeliveryView();if(DeliveryItem.held)return;deliverySearch-=dt;if(deliverySearch>0||Season.Hybrid.time<Season.Tools.nextDeliveryAt)return;deliverySearch=2;
  if(FreeWood<2||FreeResin<1||Gatherers.Any(g=>g.ToolAction))return;
  foreach(var tool in new[]{VillageTool.BoundAxe,VillageTool.CultivatingHoe}){if(FreeResin<ToolTechnologyState.ResinCost(tool))continue;int maker=System.Array.FindIndex(Season.Tools.learners,m=>m.Knows(tool));if(maker<0)continue;foreach(var g in Gatherers.OrderBy(g=>Vector3.Distance(g.transform.position,StoreApproach))){int person=System.Array.IndexOf(Gatherers,g);var social=g.GetComponent<VillagerSocial>();if(g.GetComponent<VillagerRoutine>().role!=(tool==VillageTool.BoundAxe?VillagerRoutine.Role.Forester:VillagerRoutine.Role.Farmer)||Season.Tools.learners[person].Owns(tool)||g.GetComponent<CarryItem>().held||social.RecentFright||social.Memory.injury>=.7f||Vector3.Distance(g.transform.position,StoreApproach)>Navigation.Scale*140)continue;if(!Navigation.Sample(StoreApproach+Vector3.right*Navigation.Scale*5,Navigation.creature,4,out var ground)||!deliveryGod.CanReach(ground))continue;
    if(!Season.Tools.OfferDelivery(State,maker,person,tool,Season.Hybrid.time,Navigation.ToNav(Navigation.ProjectFoot(ground,Navigation.creature))))continue;DeliveryItem.transform.position=DeliveryItem.home=Navigation.ToWorld(Delivery.grounded);DeliveryItem.GetComponent<CreatureAffordance>().cooldown=0;DeliveryView();social.GetComponent<VillagerAffect>()?.Learned();if(g.CanWatchTools)g.GetComponent<VillagerRoutine>().Celebrate(DeliveryItem.transform);deliveryGod.Journal.Add(Season.Hybrid.time,"tool handoff opportunity",CreatureAction.RespondToGuidance,"workshop-tool-delivery",tool+" for villager-"+person);return;
  }}
 }
 public void RetryToolApproach(){deliveryApproach=(deliveryApproach+1)%8;destinationUntil=0;destinationFound=false;}
 public bool ClaimToolDelivery(){if(!CanOfferDelivery)return false;DeliveryClaimed=true;return true;}
 public void ReleaseToolDelivery(){DeliveryClaimed=false;}
 public void CaptureToolDelivery(){if(Delivery?.Active==true&&DeliveryItem!=null&&!DeliveryItem.held&&!restoreDelivery)Delivery.grounded=Navigation.ToNav(DeliveryItem.transform.position);}
 public bool ConfirmToolDelivery(ToolDeliverySource by){var person=DeliveryPerson;if(Season.paused||person==null||DeliveryItem.held||person.GetComponent<CarryItem>().held||person.Memory.injury>=.7f||person.RecentFright||Vector3.Distance(DeliveryItem.transform.position,person.transform.position)>Navigation.Scale*10||by==ToolDeliverySource.Creature&&!DeliveryClaimed||!Season.Tools.ReceiveDelivery(State,by))return false;CaptureToolDelivery();foreach(var g in Gatherers)g.RefreshToolArt();person.GetComponent<HumanoidMotion>()?.React();person.GetComponent<VillagerAffect>()?.Learned();if(by==ToolDeliverySource.Player){deliveryGod.InvalidateLesson("Player tool delivery is not creature work");if(deliveryGod.State.guidance.status==GuidanceStatus.Active&&deliveryGod.State.guidance.target=="workshop-tool-delivery")deliveryGod.CancelGuidance("Player delivered the tool");}else{person.Memory.trust=Mathf.Clamp01(person.Memory.trust+.04f);person.Memory.affinity=Mathf.Clamp01(person.Memory.affinity+.02f);}deliveryGod.Journal.Add(Season.Hybrid.time,"tool delivered",CreatureAction.RespondToGuidance,"workshop-tool-delivery",by+": "+Delivery.tool+" equipped by villager-"+Delivery.recipient);IslandAudio.Cue(IslandSound.Discovery,person.transform.position,17321,.5f);DeliveryView();RefreshStock();return true;}
 public void PlayerToolPlaced(CarryItem item){if(item!=DeliveryItem||Delivery?.Active!=true)return;CaptureToolDelivery();if(Season.paused)Delivery.playerArrivalPending=true;else ConfirmToolDelivery(ToolDeliverySource.Player);}
}
}
